/* decode one compact level into the full object the game engine uses */
window.arroutDecodeLevel = function (c) {
  var D = [[0,-1],[1,0],[0,1],[-1,0]], N = ['UP','RIGHT','DOWN','LEFT'], sh = window.ARROUT_SHAPES[c.shapeName] || [1, [['r',0,0,1,1]]], cells = 0;
  var arrows = c.a.map(function (f, i) {
    var pts = []; for (var k = 0; k < f.length; k += 2) pts.push({ x: f[k], y: f[k + 1] });
    var n = pts.length, dx = pts[n-1].x - pts[n-2].x, dy = pts[n-1].y - pts[n-2].y, dn = 0;
    for (var q = 0; q < 4; q++) if (D[q][0] === dx && D[q][1] === dy) dn = q;
    cells += n; return { id: i, points: pts, dir: N[dn], dirNum: dn, length: n };
  });
  return { level: c.level, difficulty: c.d, shape: c.shapeName.toLowerCase(), shapeName: c.shapeName, icon: window.ARROUT_ICONS[c.shapeName] || '\uD83E\uDDE9',
    cols: c.cols, rows: c.rows, arrowCount: arrows.length, occupiedCellCount: cells, prims: sh[1], ar: sh[0], arrows: arrows };
};
window.arroutLevelMeta = function (c) {
  var cells = 0; c.a.forEach(function (f) { cells += f.length / 2; });
  return { level: c.level, difficulty: c.d, shapeName: c.shapeName, icon: window.ARROUT_ICONS[c.shapeName] || '\uD83E\uDDE9', arrowCount: c.a.length, occupiedCellCount: cells };
};
